def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    if budget <= 0:
        return 0.0

    alive_opponents = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if not alive_opponents:
        bid = min(budget, DAILY_SALARY * 0.35)
        if hp <= 2 or no_water_days >= 1:
            bid = min(budget, DAILY_SALARY * 0.75)
        return float(max(0.0, bid))

    prev_bids = []
    prev_high = 0.0
    eric_like_high = 0.0
    desperate_count = 0
    rich_count = 0
    for opp in alive_opponents:
        if float(opp.get('budget', 0.0)) >= 120:
            rich_count += 1
        if int(opp.get('no_water_days', 0)) >= 1 or float(opp.get('hp', 0)) <= 3:
            desperate_count += 1
        prev = opp.get('previous_trace') or {}
        bidv = prev.get('bid')
        if bidv is not None:
            bidv = float(bidv)
            prev_bids.append(bidv)
            if bidv > prev_high:
                prev_high = bidv
            if bidv > eric_like_high and bidv >= 100:
                eric_like_high = bidv

    scarcity = 0
    if supply <= 16:
        scarcity = 2
    elif supply <= 19:
        scarcity = 1

    urgency = 0
    if hp <= 2 or no_water_days >= 2:
        urgency = 3
    elif hp <= 4 or no_water_days >= 1:
        urgency = 2
    elif hp <= 6:
        urgency = 1

    if prev_bids:
        ref_bid = prev_high
    else:
        ref_bid = DAILY_SALARY * 0.55

    if urgency >= 3:
        target = max(DAILY_SALARY * 1.1, ref_bid + 6.0)
        if scarcity >= 1:
            target = max(target, DAILY_SALARY * 1.35)
    elif urgency == 2:
        target = max(DAILY_SALARY * 0.82, min(ref_bid + 2.5, DAILY_SALARY * 1.05))
        if scarcity == 2:
            target = max(target, DAILY_SALARY * 0.98)
    elif urgency == 1:
        if prev_high >= 120 and scarcity == 0:
            target = DAILY_SALARY * 0.34
        else:
            target = max(DAILY_SALARY * 0.48, min(ref_bid * 0.72, DAILY_SALARY * 0.8))
            if scarcity >= 1:
                target = max(target, DAILY_SALARY * 0.62)
    else:
        if prev_high >= 120:
            target = DAILY_SALARY * 0.22
        elif prev_high >= 80:
            target = DAILY_SALARY * 0.32
        else:
            target = DAILY_SALARY * 0.44
        if scarcity == 2 and desperate_count >= 1:
            target = max(target, DAILY_SALARY * 0.58)
        elif scarcity == 1 and desperate_count >= 2:
            target = max(target, DAILY_SALARY * 0.52)

    if day >= 8:
        target = max(target, DAILY_SALARY * 0.6)
        if urgency >= 2:
            target = max(target, DAILY_SALARY * 0.95)

    if budget < DAILY_SALARY * 0.8:
        target = min(target, budget)
    elif budget < DAILY_SALARY * 1.5 and urgency == 0:
        target = min(target, DAILY_SALARY * 0.45)

    if rich_count == 1 and prev_high >= 120 and urgency == 0 and scarcity == 0:
        target = min(target, DAILY_SALARY * 0.2)

    bid = max(0.0, min(budget, target))
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    my_hp = float(my_status['hp'])
    my_budget = float(my_status['budget'])
    my_no_water_days = int(my_status['no_water_days'])

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opponents.append((opp_id, opp))

    # If no opponents are alive, spend enough to secure water.
    if not alive_opponents:
        bid = DAILY_SALARY * 0.6
        return min(my_budget, bid)

    # Read only yesterday's immediate trace bids.
    prev_bids = []
    for _, opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev['bid']))
            except Exception:
                pass

    # Estimate pressure from highest previous bid.
    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Base bid depends on supply tightness.
    # When supply is close to WATER_REQ, competition likely increases.
    tightness = (MAX_SUPPLY - supply) / (MAX_SUPPLY - MIN_SUPPLY)  # higher => tighter
    tightness = max(0.0, min(1.0, tightness))

    # My urgency: low hp or many no-water days.
    urgency = 0.0
    if my_hp <= 2:
        urgency += 1.0
    if my_hp <= 4:
        urgency += 0.6
    if my_no_water_days >= 2:
        urgency += 0.6
    if my_no_water_days >= 3:
        urgency += 0.8

    # If someone was bidding very high yesterday, raise my bid to avoid being crowded out.
    # Otherwise keep a moderate bid to conserve budget.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        # Aggressive market: bid slightly below their top to still win when possible.
        target = highest_prev_bid * 0.85
        if urgency > 0.0:
            target = max(target, DAILY_SALARY * (0.65 + 0.25 * urgency))
    elif highest_prev_bid >= DAILY_SALARY * 0.55:
        target = max(DAILY_SALARY * (0.45 + 0.25 * tightness), highest_prev_bid * 0.75)
        if urgency > 0.0:
            target = max(target, DAILY_SALARY * (0.55 + 0.25 * urgency))
    else:
        # Low observed pressure: bid enough to secure water when tight.
        target = DAILY_SALARY * (0.35 + 0.25 * tightness)
        if urgency > 0.0:
            target = max(target, DAILY_SALARY * (0.55 + 0.2 * urgency))

    # Ensure bid is feasible.
    # Also avoid overspending: keep some budget for later days.
    # If my budget is low, bid close to remaining budget.
    budget_safety_factor = 0.75
    if my_budget <= DAILY_SALARY * 0.8:
        budget_safety_factor = 0.95

    bid = min(my_budget * budget_safety_factor, target)

    # If supply is extremely tight relative to my requirement, ensure bid is not too low.
    if supply <= float(WATER_REQ) + 1.0:
        min_bid = DAILY_SALARY * (0.55 + 0.15 * tightness)
        bid = max(bid, min_bid)

    # Final clamp.
    if bid < 0.0:
        bid = 0.0
    if bid > my_budget:
        bid = my_budget

    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.2)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        avg_prev = sum(yesterday_bids) / len(yesterday_bids)
        bid = avg_prev * 1.05
    else:
        bid = DAILY_SALARY * 0.6

    if my_status['hp'] <= 3:
        bid = max(bid, DAILY_SALARY * 0.9)

    return min(my_status['budget'], float(bid))
